import React, { useEffect, useState, useRef } from "react";
import { useNavigate } from "react-router-dom";

export default function Home({
  token,
  onLogout,
  onShowDeposit,
  onShowWithdraw,
  onShowAdminWithdraw,
  onShowAdminDepositRequests,
  onShowHistory,
  onShowAdminUserHistory,
  onShowLudoMatch,
}) {
  const navigate = useNavigate();
  const [balance, setBalance] = useState(null);
  const [loading, setLoading] = useState(true);
  const [isAdmin, setIsAdmin] = useState(false);
  const [userProfile, setUserProfile] = useState(null);
  const [editing, setEditing] = useState(false);
  const [displayName, setDisplayName] = useState("");
  const [avatarFile, setAvatarFile] = useState(null);
  const fileInputRef = useRef();

  useEffect(() => {
    if (!token) return;
    const fetchUserData = async () => {
      try {
        const res = await fetch("http://localhost:8080/api/user/profile", {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (!res.ok) throw new Error("Failed to fetch user profile");
        const data = await res.json();
        setUserProfile(data);
        setDisplayName(data.displayName || "");
        setIsAdmin(data.role?.toLowerCase() === "admin");
      } catch (err) {
        console.error("Failed to get user profile:", err);
      }
    };
    fetchUserData();
  }, [token]);

  useEffect(() => {
    if (!token) return;
    const fetchBalance = async () => {
      try {
        const res = await fetch("http://localhost:8080/api/user/balance", {
          headers: { Authorization: `Bearer ${token}` },
        });
        const data = await res.json();
        if (res.ok && data.balance != null && !isNaN(data.balance)) {
          setBalance(parseFloat(data.balance));
        } else {
          throw new Error("Invalid balance response");
        }
      } catch (error) {
        console.error("Failed to fetch balance:", error);
        setBalance("Error");
      } finally {
        setLoading(false);
      }
    };
    fetchBalance();
  }, [token]);

  const renderBalance = () => {
    if (loading) return "Loading...";
    if (balance === "Error") return "Balance unavailable";
    return `৳ ${balance.toFixed(2)}`;
  };

  // Profile saving, avatar handling, etc. remain the same (omitted here for brevity)
  // ...

  const renderAvatar = () => {
    if (avatarFile) return URL.createObjectURL(avatarFile);
    if (userProfile?.avatarUrl) return `http://localhost:8080${userProfile.avatarUrl}`;
    return `https://ui-avatars.com/api/?name=${encodeURIComponent(userProfile?.displayName || "U")}`;
  };

  return (
    <div className="min-h-screen bg-gray-100 font-sans">
      {/* Header */}
      <header className="bg-gray-800 text-white flex justify-between items-center px-6 py-4 shadow-md">
        <div className="text-xl font-semibold">🎮 Ludo Dashboard</div>
        <div className="flex items-center space-x-4 text-sm">
          <span className="bg-cyan-600 px-3 py-1 rounded-full font-bold">
            {renderBalance()}
          </span>
          <button
            onClick={onLogout}
            className="bg-red-500 hover:bg-red-600 px-4 py-2 rounded-md font-semibold"
          >
            🚪 Logout
          </button>
        </div>
      </header>

      {/* Main content remains unchanged */}
      <main className="flex justify-center items-start px-4 py-10">
        <div className="bg-white w-full max-w-3xl rounded-lg shadow-xl p-8 space-y-6">
          {/* Title and editing profile code here... */}
          {/* Profile Info and Buttons same as before */}
          {/* You can copy-paste your existing code here */}
        </div>
      </main>
    </div>
  );
}

function ActionButton({ text, onClick, className }) {
  return (
    <button
      onClick={onClick}
      className={`text-white font-semibold py-3 rounded-md shadow-md hover:opacity-90 transition ${className}`}
    >
      {text}
    </button>
  );
}
